import requests


def fetch_profile_claims(access_token):
    headers = {'Authorization': f'Bearer {access_token}'}
    response = requests.get('https://graph.microsoft.com/v1.0/me', headers=headers)
    response.raise_for_status()
    return response.json()

import os


def get_identity_client():
    return {
        'client_id': os.getenv('AZURE_CLIENT_ID'),
        'client_secret': os.getenv('AZURE_CLIENT_SECRET'),
        'tenant_id': os.getenv('AZURE_TENANT_ID')
    }

class OAuthResponse:
    def __init__(self, data):
        self.access_token = data.get('access_token')
        self.id_token = data.get('id_token')
        self.refresh_token = data.get('refresh_token')
        self.expires_in = data.get('expires_in')


class ProfileClaims:
    def __init__(self, data):
        self.user_id = data.get('id')
        self.display_name = data.get('displayName')
        self.email = data.get('mail')

def summarize_audit_events(events):
    summary = {}
    for event in events:
        if event['type'] not in summary:
            summary[event['type']] = 0
        summary[event['type']] += 1
    return summary

def moderate_claims(claims):
    moderated_claims = {}
    for key, value in claims.items():
        if isinstance(value, str):
            moderated_claims[key] = value.strip()
        else:
            moderated_claims[key] = value
    return moderated_claims

